namespace SecretCustomer.Core.Enums;

public enum QuestionType
{
    MultipleChoice = 1,
    Likert = 2,
    Star = 3,
    Text = 4,
    YesNo = 5  // YENİ
}

private decimal? CalculateEarnedPoints(Question question, SubmitAnswerDto answer)
{
    if (answer.IsNA)
        return null;

    return question.Type switch
    {
        QuestionType.MultipleChoice => question.Points,
        QuestionType.Likert => (answer.AnswerNumeric ?? 0) * (question.Points / 5.0m),
        QuestionType.Star => (answer.AnswerNumeric ?? 0) * (question.Points / 5.0m),
        QuestionType.Text => null,
        QuestionType.YesNo => (answer.AnswerNumeric == 1) ? question.Points : 0, // YENİ: 1=Evet, 0=Hayır
        _ => 0
    };
}
